SELECT define_id, COUNT(CASE WHEN status = 0 THEN 1 END) AS running_count, COUNT(CASE WHEN status = 1 THEN 1 END) AS success_count, COUNT(CASE WHEN status = 2 OR status = 3 THEN 1 END) AS fail_count FROM groupon_instance WHERE id IN
#{grouponInstanceId}
GROUP BY define_id
